const express = require('express');
const router = express.Router();
const { generateRegistrationOptions } = require('@simplewebauthn/server');
const { isoBase64URL } = require('@simplewebauthn/server/helpers');

router.post('/api/webauthn/register/options', authenticateJwt, async (req, res) => {
  const targetUserId = req.user.id;
  const username = req.user.email;

  const userPasskeys = await PasskeyModel.find({ userId: targetUserId });
  const options = await generateRegistrationOptions({
    rpName: 'Enterprise Shield SSO',
    rpID: 'shield.enterprise.io',
    userID: isoBase64URL.toBuffer(targetUserId),
    userName: username,
    attestationType: 'none',
    excludeCredentials: userPasskeys.map(key => ({
      id: key.credentialID,
      transports: key.transports
    }))
  });

  await ChallengeCache.set(`reg_chal:${targetUserId}`, options.challenge, 300);
  return res.json(options);
});
